public class Main {
    static final long MOD = 998244353;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] rock1 = new int[3];
        int[] sci1 = new int[3];
        int[] paper1 = new int[3];
        int[] rock2 = new int[3];
        int[] sci2 = new int[3];
        int[] paper2 = new int[3];

        for (int i = 0; i < 3; i++) {
            rock1[i] = sc.nextInt();
            sci1[i] = sc.nextInt();
            paper1[i] = sc.nextInt();
        }

        for (int i = 0; i < 3; i++) {
            rock2[i] = sc.nextInt();
            sci2[i] = sc.nextInt();
            paper2[i] = sc.nextInt();
        }

        System.out.println(minimum(n, rock1, sci1, paper1, rock2, sci2, paper2));
        System.out.println(maximum(n, rock1, sci1, paper1, rock2, sci2, paper2));
    }

    static int minimum(int n, int[] rock1, int[] sci1, int[] paper1, int[] rock2, int[] sci2, int[] paper2) {
        int ans = n;
        int[][] l = new int[3][2];
        int[][] l1 = new int[(int)Math.pow(3, n)][2][2];
        int[][] l2 = new int[(int)Math.pow(3, n)][2][2];

        for (int i = 0; i < 3; i++) {
            l[i][0] = rock1[i];
            l[i][1] = i + 1;
        }

        for (int i = 0; i < (int)Math.pow(3, n); i++) {
            l1[i] = l.clone();
        }

        for (int i = 0; i < 3; i++) {
            l[i][0] = rock2[i];
            l[i][1] = i + 1;
        }

        for (int i = 0; i < (int)Math.pow(3, n); i++) {
            l2[i] = l.clone();
        }

        for (int i = 0; i < (int)Math.pow(3, n); i++) {
            for (int j = 0; j < (int)Math.pow(3, n); j++) {
                ans = Math.min(ans, give(l1[i], l2[j]));
            }
        }

        return ans;
    }

    static int give(int[][] l1, int[][] l2) {
        int ans = 0;
        int[] curr1 = new int[2];
        int[] curr2 = new int[2];
        int[][] tempL1 = l1.clone();
        int[][] tempL2 = l2.clone();

        while (tempL1.length > 0 && tempL2.length > 0) {
            try {
                if (curr1[0] == 0) {
                    curr1 = tempL1[0].clone();
                    tempL1 = Arrays.copyOfRange(tempL1, 1, tempL1.length);
                }

                if (curr2[0] == 0) {
                    curr2 = tempL2[0].clone();
                    tempL2 = Arrays.copyOfRange(tempL2, 1, tempL2.length);
                }
            } catch (ArrayIndexOutOfBoundsException e) {
                return ans;
            }

            ans += Math.max(0, Math.min(curr1[0], curr2[0]) * match(curr1[1], curr2[1]));
            // System.out.println(curr1 + " " + curr2);

            if (curr1[0] < curr2[0]) {
                curr2[0] -= curr1[0];
                curr1 = new int[2];
            } else if (curr1[0] > curr2[0]) {
                curr1[0] -= curr2[0];
                curr2 = new int[2];
            } else {
                curr1 = new int[2];
                curr2 = new int[2];
            }
        }

        return ans;
    }

    static int match(int a, int b) {
        if (a == b) {
            return 0;
        } else if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) {
            return 1;
        } else {
            return -1;
        }
    }

    static int maximum(int n, int[] rock1, int[] sci1, int[] paper1, int[] rock2, int[] sci2, int[] paper2) {
        int ans = 0;
        for (int i = 0; i < rock1.length; i++) {
            for (int j = 0; j < rock2.length; j++) {
                ans += Math.min(rock1[i], rock2[j]);
            }
        }

        for (int i = 0; i < sci1.length; i++) {
            for (int j = 0; j < paper2.length; j++) {
                ans += Math.min(sci1[i], paper2[j]);
            }
        }

        for (int i = 0; i < paper1.length; i++) {
            for (int j = 0; j < sci2.length; j++) {
                ans += Math.min(paper1[i], sci2[j]);
            }
        }

        return ans;
    }
}

