import java.util.stream.Stream;

public class Main {

    public static void main(String[] args) throws IOException {

        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine().trim());
        int[] inputA = Arrays.stream(reader.readLine().trim().split(" ")).mapToInt(Integer::parseInt).toArray();
        int[] inputB = Arrays.stream(reader.readLine().trim().split(" ")).mapToInt(Integer::parseInt).toArray();

        int[] inputA2 = inputA.clone();
        int[] inputB2 = inputB.clone();

        System.out.println(n - getLostMaxFast(inputA2, inputB2), getWonMaxFast(inputA, inputB));
    }

    static int getWonMaxFast(int[] inputA, int[] inputB) {
        int[] wins = new int[3];
        for (int i = 0; i < 3; i++) {
            int good = (i + 1) % 3;
            wins[i] = Math.min(inputA[i], inputB[good]);
            inputA[i] -= wins[i];
            inputB[good] -= wins[i];
        }
        return Arrays.stream(wins).sum();
    }

    static int getLostMaxFast(int[] inputA, int[] inputB) {
        int[][] waysToLose = new int[][] {{0, 2}, {1, 0}, {2, 1}, {0, 0}, {1, 1}, {2, 2}};
        int[][] allWaysToLosePermutations = Stream.of(waysToLose).flatMap(Arrays::stream).toArray(int[][]::new);

        int maxLost = 0;

        for (int[] permutation : allWaysToLosePermutations) {
            int[] losts = new int[3];
            int[] inputACopy = inputA.clone();
            int[] inputBCopy = inputB.clone();

            for (int[] wayToLose : permutation) {
                int lost_add = Math.min(inputACopy[wayToLose[0]], inputBCopy[wayToLose[1]]);
                inputACopy[wayToLose[0]] -= lost_add;
                inputBCopy[wayToLose[1]] -= lost_add;
                losts[wayToLose[0]] += lost_add;
            }

            int lostSum = Arrays.stream(losts).sum();

            if (lostSum > maxLost) {
                maxLost = lostSum;
            }
        }

        return maxLost;
    }
}

