import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    static BufferedReader br;
    static PrintWriter out;
    static StringTokenizer st;

    static String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    static class Dinic {

        int n;
        int[][] links;
        int[] depth;
        int[] progress;
        int[][] pos;

        Dinic(int n) {
            this.n = n;
            this.links = new int[n][];
            this.depth = new int[n];
            this.progress = new int[n];
            this.pos = new int[n][];
        }

        void addEdge(int from, int to, int cap) {
            pos[from] = Arrays.copyOf(pos[from], pos[from].length + 1);
            links[from] = Arrays.copyOf(links[from], links[from].length + 1);
            links[from][links[from].length - 1] = new int[] { cap, to, links[to].length };
            links[to] = Arrays.copyOf(links[to], links[to].length + 1);
            links[to][links[to].length - 1] = new int[] { 0, from, pos[from].length - 1 };
        }

        void bfs(int s) {
            Arrays.fill(depth, -1);
            depth[s] = 0;
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int[] edge : links[v]) {
                    int to = edge[1], idx = edge[2];
                    if (edge[0] > 0 && depth[to] < 0) {
                        depth[to] = depth[v] + 1;
                        q.add(to);
                    }
                }
            }
        }

        void dfs(int v, int t, int flow) {
            if (v == t) {
                return;
            }
            for (int i = progress[v]; i < links[v].length; i++) {
                progress[v] = i;
                int[] edge = links[v][i];
                if (edge[0] == 0 || depth[v] >= depth[edge[1]]) {
                    continue;
                }
                dfs(edge[1], t, Math.min(flow, edge[0]));
                edge[0] -= flow;
                links[edge[1]][edge[2]][0] += flow;
                return;
            }
        }

        int flow(int s, int t) {
            int flow = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0) {
                    return flow;
                }
                Arrays.fill(progress, 0);
                dfs(s, t, Integer.MAX_VALUE);
                while (true) {
                    int currentFlow = 0;
                    for (int i = 0; i < progress.length; i++) {
                        if (depth[i] != -1 && progress[i] < links[i].length) {
                            currentFlow += links[i][progress[i]][0];
                        }
                    }
                    if (currentFlow == 0) {
                        break;
                    }
                    flow += currentFlow;
                    dfs(s, t, currentFlow);
                }
            }
        }

        int[][] getEdges() {
            int M = pos.length;
            int[][] res = new int[M][4];
            for (int i = 0; i < M; i++) {
                int[] edge = links[pos[i][0]][pos[i][1]];
                res[i] = new int[] { pos[i][0], edge[1], edge[0] + links[edge[1]][edge[2]][0], links[edge[1]][edge[2]][0] };
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        int N = nextInt();
        int M = 3;
        int[] A = new int[M];
        for (int i = 0; i < M; i++) {
            A[i] = nextInt();
        }

        int ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A[i], A[(i + 1) % M]);
        }

        Dinic dinic = new Dinic(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;
        for (int i = 0; i < M; i++) {
            dinic.addEdge(s, i, N);
            dinic.addEdge(M + i, t, A[i]);
            dinic.addEdge(i, M + i, A[i]);
            dinic.addEdge(i, M + (i - 1) % M, A[i]);
        }
        int ans2 = N - dinic.flow(s, t);

        out.println(ans2 + " " + ans1);
        out.close();
    }

