        System.out.print("Enter the value of n and modulus separated by space: ");
        String[] input = scanner.nextLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int mod = Integer.parseInt(input[1]);

        int[] mem = new int[n + 1];
        int su = 1;
        mem[1] = 1;

        for (int i = 2; i <= n; i++) {
            int sq = (int) Math.sqrt(i) + 1;
            int cur = su;

            for (int f = 2; f <= sq; f++) {
                cur = (cur + mem[i / f]) % mod;
            }

            int be = i;
            for (int j = 1; j <= i / sq; j++) {
                int nxt = i / (j + 1);
                cur = (cur + (be - nxt) * mem[j]) % mod;
                be = nxt;
            }

            su = (su + cur) % mod;
            mem[i] = cur;
        }
        System.out.println(mem[n]);
    }
}
