        int n = Integer.parseInt(input[0]);
        int M = Integer.parseInt(input[1]);

        int[][] D = new int[n + 1][];
        for (int i = 2; i <= n; i++) {
            D[i] = new int[(n - i) / i + 1];
            for (int j = 0; (j = i * (j + 1)) <= n; j++)
                D[i][(n - j) / i]++;
        }

        int[] F = new int[n + 1];
        F[1] = 1;
        F[2] = 2;
        for (int x = 3; x <= n; x++) {
            F[x] = (2 * F[x - 1] + F[x / (x - 1)]) % M;
            int S = 0;
            for (int d : D[x])
                if (2 <= d && d <= x - 2)
                    S = (S + F[x / d] - F[(x - 1) / d]) % M;
            F[x] = (F[x] + S) % M;
        }

        out.println(F[n] % M);
        out.close();
    }
}

