public class Main {
    public static List<Integer> primes = new ArrayList<>();
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        System.out.println(process(n, m));
    }

    public static void generatePrimes() {
        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) {
                    break;
                }
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(p);
            }
        }
    }

    public static HashMap<Integer, Integer> factor(int n) {
        HashMap<Integer, Integer> d = new HashMap<>();
        for (int p : primes) {
            if (p * p > n) {
                break;
            }
            if (n % p == 0) {
                int c = 0;
                while (n % p == 0) {
                    n = n / p;
                    c++;
                }
                d.put(p, c);
            }
        }
        if (n > 1) {
            d.put(n, 1);
        }
        return d;
    }

    public static List<Integer> factors(int n) {
        HashMap<Integer, Integer> d = factor(n);
        List<Integer> answer = new ArrayList<>();
        answer.add(1);
        for (int p : d.keySet()) {
            List<Integer> a2 = new ArrayList<>();
            for (int x : answer) {
                for (int i = 0; i <= d.get(p); i++) {
                    a2.add(x * (int) Math.pow(p, i));
                }
            }
            answer = a2;
        }
        return answer;
    }

    public static int process(int n, int m) {
        HashMap<Integer, Integer> f_dict = new HashMap<>();
        f_dict.put(0, 0);
        f_dict.put(1, 1);
        f_dict.put(2, 2);
        generatePrimes();
        for (int i = 3; i <= n; i++) {
            f_dict.put(i, 2 * f_dict.get(i - 1));
            for (int x : factors(i)) {
                if (2 <= x && x <= i) {
                    f_dict.put(i, f_dict.get(i) + (f_dict.get(i / x) - f_dict.get((i - 1) / x)) % m);
                    f_dict.put(i, f_dict.get(i) % m);
                }
            }
            f_dict.put(i, f_dict.get(i) % m);
        }
        return f_dict.get(n);
    }
}

