        for (int i = 0; i < p; i++) {
            if (f[(k * i) % p] != (k * f[i]) % p) {
                return false;
            }
        }
        return true;
    }

    static long gen(int[] f, int p, int k, int i) {
        if (i == p) {
            return isGood(f, p, k) ? 1 : 0;
        } else {
            long ans = 0;
            for (int j = 0; j < p; j++) {
                f[i] = j;
                ans += gen(f, p, k, i + 1);
            }
            return ans;
        }
