        Set<Integer> used = new HashSet<>();
        for (int j = 0; j < p; j++) {
            if (!used.contains(j)) {
                num++;
            }
            int i = j;
            while (!used.contains(i)) {
                used.add(i);
                i = (i * k) % p;
            }
        }
