        int[] k = new int[P];
        for (int i = 0; i < P; i++) {
            k[i] = (int) ((K * i) % P);
        }

        if (K == 0) {
            System.out.println(pow(P, P - 1, M));
            return;
        }

        boolean[] f = new boolean[P];
        int[] c = new int[P];
        int ans = 1;
        for (int i = 0; i < P; i++) {
            if (f[i]) continue;

            int cnt = 1;
            int u = i;
            f[u] = true;
            while (!f[k[u]]) {
                u = k[u];
                f[u] = true;
                cnt++;
            }

            c[cnt]++;
        }

        for (int i = 1; i < P; i++) {
            if (c[i] != 0) {
                int cnt = i * c[i] + (i > 1 ? 1 : 0);
                ans = (int) ((ans * pow(cnt, c[i], M)) % M);
            }
        }

        System.out.println(ans);
    }

    public static long pow(long n, long k, long M) {
        long res = 1;
        while (k > 0) {
            if ((k & 1) > 0) {
                res = (res * n) % M;
            }
            n = (n * n) % M;
            k >>= 1;
        }
        return res;
    }
}
