            s = s.substring(0, index + 1) + '.' + s.substring(index + 4, s.length() - 1);
            index = s.substring(1, s.length() - 1).indexOf("dot");
        }
        return s;
    }

    public static String replaceAt(String s) {
        int index = s.substring(1, s.length() - 1).indexOf("at");
        if (index != -1) {
            s = s.substring(0, index + 1) + '@' + s.substring(index + 3, s.length() - 1);
        }
        return s;
    }
