import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[] a = new int[20];
        for (int i = 0; i < 20; i++) {
            a[i] = scanner.nextInt();
        }
        int[] b = new int[1 << (n / 2)];
        for (int i = 0; i < (1 << (n / 2 + n % 2)); i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) != 0) {
                    t += a[j];
                }
                k = k >> 1;
            }
            b[i] = t % m;
        }
        Arrays.sort(b);
        int otv = 0;
        for (int i = 0; i < (1 << (n / 2)); i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) != 0) {
                    t += a[j + n / 2 + n % 2];
                }
                k = k >> 1;
            }
            t = t % m;
            int index = binarySearch(b, m - t - 1);
            if (index < b.length) {
                int t2 = b[index];
                if (t2 > m - t - 1) {
                    if (index - 1 >= 0) {
                        t2 = b[index - 1];
                    }
                } else {
                    index--;
                }
            } else {
                index = b.length - 1;
                t2 = b[index];
            }
            otv = Math.max(otv, (t + t2) % m, (t + b[b.length - 1]) % m);
        }
        System.out.println((otv % m));
    }

    static int binarySearch(int[] array, int target) {
        int left = 0;
        int right = array.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (array[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

