            start += data.length / 2;
            stop += data.length / 2;
            int res = default_val;
            while (start < stop) {
                if (start % 2 == 1) {
                    res = func(res, data[start]);
                    start++;
                }
                if (stop % 2 == 1) {
                    stop--;
                    res = func(res, data[stop]);
