import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        scanner.nextLine();  // Consume newline left-over

        Map<Integer, Map<Integer, Map<Integer, Integer>>> memo = new HashMap<>();
        for (int i = 0; i <= n; i++) {
            memo.put(i, new HashMap<>());
            memo.get(i).put(0, new HashMap<>());
            memo.get(i).put(1, new HashMap<>());
        }

        System.out.println(solve(n, 0, 1, memo, mod));
    }

    public static int invnum(int[] seq) {
        int N = seq.length;
        int res = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (seq[i] > seq[j]) {
                    res++;
                }
            }
        }
        return res;
    }

    public static int naive(int N, int k, boolean flag, int mod) {
        int res = 0;
        for (int[] p : getPermutations(N)) {
            for (int[] q : getPermutations(N)) {
                if (((Arrays.compare(p, q) < 0) || !flag) && (invnum(p) - invnum(q) > k)) {
                    res++;
                }
            }
        }
        return res;
    }

    public static int[][] getPermutations(int N) {
        int[][] permutations = new int[N][N];
        permute(new int[N], 0, permutations);
        return permutations;
    }

    public static void permute(int[] arr, int index, int[][] permutations) {
        if (index == arr.length) {
            permutations[permutations.length - 1][index] = arr[0];
            return;
        }
        for (int i = 0; i <= arr.length; i++) {
            arr[index] = i;
            permute(arr, index + 1, permutations);
        }
    }

    public static int compare(int[] a, int[] b) {
        for (int i = 0; i < a.length; i++) {
            if (a[i] < b[i]) {
                return -1;
            } else if (a[i] > b[i]) {
                return 1;
            }
        }
        return 0;
    }

    public static int solve(int N, int k, boolean flag, Map<Integer, Map<Integer, Map<Integer, Integer>>> memo, int mod) {
        if (memo.get(N).get(flag ? 1 : 0).get(k) != null) {
            return memo.get(N).get(flag ? 1 : 0).get(k);
        }

        if (N == 1) {
            int res = -1;
            if (flag) {
                res = 0;
            } else {
                if (k < 0) {
                    res = 1;
                } else {
                    res = 0;
                }
            }
            memo.get(N).get(flag ? 1 : 0).put(k, res);
            return res;
        }

        int invnum_INF = (N * (N - 1)) / 2;
        if (k < -invnum_INF - 1) {
            int res = solve(N, -invnum_INF - 1, flag, memo, mod);
            memo.get(N).get(flag ? 1 : 0).put(k, res);
            return res;
        }

        if (k >= invnum_INF) {
            memo.get(N).get(flag ? 1 : 0).put(k, 0);
            return 0;
        }

        int res = 0;

        for (int delta = -N + 1; delta < N; delta++) {
            if (flag && delta > 0) {
                continue;
            }

            int wt = Math.min(N - delta, delta + N);
            res += (solve(N - 1, k - delta, delta == 0 && flag, memo, mod) * wt + mod) % mod;
            res %= mod;
        }

        memo.get(N).get(flag ? 1 : 0).put(k, res);
        return res;
    }
}

