    static long pow(long x, int n) {
        long res = 1;
        while (n > 0) {
            if ((n & 1) == 1) {
                res = res * x % MOD;
            }
            x = x * x % MOD;
            n >>= 1;
        }
        return res;
    }

    static long euler_func(int n) {
        Set<Long> p = new HashSet<>();
        for (long i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                p.add(i);
                n /= i;
            }
        }
        if (n > 1) {
            p.add((long) n);
        }
        long x = 1;
        for (long i : p) {
            x *= (i - 1);
            x /= i;
        }
        return x;
    }

