    static class SegmentTree {
        int n;
        long[] tree;

        public SegmentTree(int n) {
            this.n = n;
            tree = new long[4 * n];
        }

        public void update(int i, long x) {
            update(0, 0, n - 1, i, x);
        }

        private void update(int node, int start, int end, int i, long x) {
            if (start == end) {
                tree[node] = x;
            } else {
                int mid = (start + end) / 2;
                if (start <= i && i <= mid) {
                    update(2 * node + 1, start, mid, i, x);
                } else {
                    update(2 * node + 2, mid + 1, end, i, x);
                }
                tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
            }
        }

        public long query(int s, int t) {
            return query(0, 0, n - 1, s, t);
        }

        private long query(int node, int start, int end, int s, int t) {
