                return 0;
            } else if (start >= s && end <= t) {
                return tree[node];
            } else {
                int mid = (start + end) / 2;
                return query(2 * node + 1, start, mid, s, t) + query(2 * node + 2, mid + 1, end, s, t);
            }
        }
    }

