        }
        all.put(lo + "," + hi, 0);
        all.put(lo + "," + hi, all.get(lo + "," + hi) + searchall(lo + 1, hi));
        all.put(lo + "," + hi, all.get(lo + "," + hi) + searchall(lo, hi - 1));
        for (int i = lo + 1; i < hi; i++) {
            all.put(lo + "," + hi, all.get(lo + "," + hi) + searchall(lo, i - 1) * searchall(i + 1, hi));
        }
        return all.get(lo + "," + hi);
