		System.out.print("Enter the number of people and houses: ");
		String[] input = scanner.nextLine().split(" ");
		int n = Integer.parseInt(input[0]);
		int h = Integer.parseInt(input[1]);
		int[][] dp = new int[n + 1][n + 1];

		for (int i = 0; i <= n; i++) {
			dp[i][0] = 1;
		}

		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= n; j++) {
				for (int k = 0; k < i; k++) {
					dp[i][j] += dp[k][j - 1] * dp[i - 1 - k][j - 1];
				}
			}
		}

		int result = dp[n][n] - (h > 0 ? dp[n][Math.min(h - 1, n)] : 0);
		System.out.println(result);
	}
}
