        int h = scanner.nextInt();
        scanner.close();

        System.out.println(func1(n) - func2(n, h));
    }

    public static int func1(int n) {
        if (n < 0)
            return 0;
        if (n < 2)
            return 1;
        if (!tab1.containsKey(n)) {
            int r = 0;
            for (int i = 0; i <= n; i++) {
                r += func1(i) * func1(n - i);
            }
            tab1.put(n, r);
        }
        return tab1.get(n);
    }

    public static int func2(int n, int h) {
        if (n < 0 || h <= 0 || n >= 1 << (h - 1))
            return 0;
        if (n < 2)
            return 1;
        if (n < h)
            return func1(n);
        if (!tab2.containsKey(n)) {
            HashMap<Integer, Integer> map = new HashMap<>();
            for (int i = 0; i < n; i++) {
                map.put(i, func2(i, h - 1));
            }
            tab2.put(n, map);
        }
        return tab2.get(n).get(n - 1);
    }

